create extension if not exists pgcrypto;
create table public.ingredients(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null check(char_length(trim(name)) between 1 and 120), unit text not null check(unit in ('g','kg','ml','l','each')), pack_quantity numeric(12,3) not null check(pack_quantity>0), pack_cost numeric(12,2) not null check(pack_cost>=0), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.recipes(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null check(char_length(trim(name)) between 1 and 160), category text not null default 'Other', menu_price numeric(12,2) not null default 0 check(menu_price>=0), servings numeric(12,3) not null default 1 check(servings>0), notes text not null default '', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.recipe_ingredients(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, recipe_id uuid not null references public.recipes(id) on delete cascade, ingredient_id uuid not null references public.ingredients(id) on delete restrict, quantity numeric(12,3) not null check(quantity>0), created_at timestamptz not null default now(), unique(recipe_id,ingredient_id));
create index ingredients_user_idx on public.ingredients(user_id); create index recipes_user_idx on public.recipes(user_id); create index recipe_ingredients_user_idx on public.recipe_ingredients(user_id);
alter table public.ingredients enable row level security; alter table public.recipes enable row level security; alter table public.recipe_ingredients enable row level security;
create policy "ingredient owner" on public.ingredients for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy "recipe owner" on public.recipes for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy "recipe line owner" on public.recipe_ingredients for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()) and exists(select 1 from public.recipes r where r.id=recipe_id and r.user_id=(select auth.uid())) and exists(select 1 from public.ingredients i where i.id=ingredient_id and i.user_id=(select auth.uid())));
